using UnityEngine;
using Verse;

namespace ActualGodMode
{
    /// <summary>
    /// The god's global pool of Divine Power, generated by worship and spent on miracles.
    /// </summary>
    public class DivinePower : GameComponent
    {
        public const float BaseMaxPower = 100f;

        private float power;
        private float lifetimePower;

        public static DivinePower Instance => Current.Game?.GetComponent<DivinePower>();

        public float Power => power;
        public float LifetimePower => lifetimePower;
        /// <summary>Base cap plus the bonus of the best temple the god has.</summary>
        public float MaxPower
        {
            get
            {
                float bonus = 0f;
                foreach (Map map in Find.Maps)
                {
                    CompShrine comp = ShrineUtility.ShrineOn(map)?.TryGetComp<CompShrine>();
                    if (comp != null)
                    {
                        bonus = Mathf.Max(bonus, comp.Temple.Tier.powerCapBonus);
                    }
                }
                return BaseMaxPower + bonus;
            }
        }

        /// <summary>True once the god has ever been worshipped or a shrine exists; controls the readout.</summary>
        public bool Revealed => lifetimePower > 0f || ShrineUtility.AnyShrineExists();

        public DivinePower(Game game)
        {
        }

        public void Add(float amount)
        {
            if (amount <= 0f)
            {
                return;
            }
            float before = power;
            power = Mathf.Min(power + amount, MaxPower);
            lifetimePower += power - before;
        }

        public bool CanAfford(float cost) => power >= cost;

        public bool TrySpend(float cost)
        {
            if (!CanAfford(cost))
            {
                return false;
            }
            power -= cost;
            return true;
        }

        public void DebugSet(float value)
        {
            power = Mathf.Clamp(value, 0f, MaxPower);
        }

        public override void ExposeData()
        {
            Scribe_Values.Look(ref power, "power", 0f);
            Scribe_Values.Look(ref lifetimePower, "lifetimePower", 0f);
        }
    }
}
